// Confirmaciones del manager, 12/10/2026. Se conservan las fichas originales.
(() => {
  const cities = {
    ardenne: 'Segur de Calafell', belestar: 'Pamplona', 'los-molinos': 'Getafe',
    'dental-ros': 'Valencia', 'implants-solutions': 'Sevilla', 'mp-ellite': 'Valdemoro',
    'dental-star-holea': 'Holea', 'dental-star-gran-via-hortaleza': 'Gran Vía Hortaleza',
    'dental-star-cabrera-mar': 'Cabrera de Mar', 'dental-star-montigala': 'Montigalá',
    'dental-star-rosaleda': 'Málaga', 'dental-star-as-cancelas': 'Santiago de Compostela',
    'dental-star-parla': 'Parla, Madrid',
    excelentia: 'Ciudad Lineal, Madrid', nuno_perez: 'Atocha, Madrid',
    usera: 'Usera, Madrid', mostoles: 'Pradillo, Móstoles, Madrid',
    vistalegre: 'Vista Alegre, Madrid', fonseca: 'Oporto, Madrid',
    smailo: 'Alcalá de Henares, Madrid', 'smailo-coslada': 'Coslada, Madrid',
    zendental: 'Las Rozas, Madrid', odos: 'Chamberí, Madrid', cirium: 'Brunete, Madrid'
  };
  cities['los-molinos'] = 'Getafe, Madrid';
  cities['mp-ellite'] = 'Valdemoro, Madrid';
  cities['dental-star-gran-via-hortaleza'] = 'Gran Vía Hortaleza, Madrid';
  const metaIds = new Set(['palomero','carranza','usera','mostoles','dentalis','jerez','oliver','rodriguezpons','adeje','excelentia','espai','caredentjerez','videsdental']);
  for (const clinic of CLINICS_DATA) {
    if (cities[clinic.id]) clinic.city = cities[clinic.id];
    if (clinic.id === 'nuno_perez') clinic.name = 'Nuño y Pérez Odontólogos';
    if (['dentalestetic-badajoz','dentalestetic-merida'].includes(clinic.id)) {
      clinic.inactive = true;
      clinic.masterIssues = ['No gestionada por ISA, confirmado por el manager.'];
    }
    if (['jerez','fonseca'].includes(clinic.id)) {
      clinic.treatments = clinic.treatments.filter(t => t !== 'ortodoncia');
      clinic.masterIssues = clinic.masterIssues.filter(s => !s.startsWith('ortodoncia:'));
    }
    const star = clinic.id.startsWith('dental-star-');
    if (star) {
      for (const data of Object.values(CLINIC_SCHEDULES[clinic.id].byTreatment)) {
        data.horarios = 'Consultar en Klinikare la disponibilidad de odontólogos generales, identificados como «ger» o «gnral».';
      }
      clinic.masterIssues = clinic.masterIssues.filter(s => !s.includes('horario no especificado'));
    }
    if (star || metaIds.has(clinic.id)) for (const t of clinic.treatments) {
      if (clinic.scriptOverrides[t] === 'simplificado') {
        const rule = OMNI_APPOINTMENT_RULES[clinic.id].treatments[t];
        Object.assign(rule, { qualification:'meta', document:false, economic:false, asnef:false, needRequired:false });
      }
    }
    if (clinic.id === 'belestar') {
      for (const data of Object.values(CLINIC_SCHEDULES[clinic.id].byTreatment)) {
        if (data.horarios) data.horarios = data.horarios.replace(/(Viernes[^\n]*?)16:00[^\n]*/i, '$116:00 (único hueco de tarde)');
      }
      clinic.masterIssues = clinic.masterIssues.filter(s => !s.startsWith('Viernes:'));
    }
  }
  const flordent = CLINICS_DATA.find(c => c.id === 'flordent');
  const data = CLINIC_SCHEDULES.flordent.byTreatment.estetica_medica;
  Object.assign(data, {
    operationalNotes: ['Estética médica: el operador confirma la cita, según indicación del manager.'],
    qualifDoc: 'DNI o NIE',
    qualifEcon: 'Mínimo obligatorio: 1.200 € de ingresos mensuales.\nDNI: nómina, pensión contributiva/jubilación, autónomos o terceros con nómina/pensión/autónomos.\nNIE: nómina, autónomos o terceros con nómina/pensión/autónomos.',
    financing: 'Entre 12 y 24 meses, dependiendo de la entidad bancaria.'
  });
  flordent.masterIssues = flordent.masterIssues.filter(s => !s.startsWith('Estética médica:'));
  flordent.scriptOverrides.estetica_medica = 'flordent_estetica';
  OMNI_APPOINTMENT_RULES.flordent.treatments.estetica_medica = {
    qualification:'operator', document:true, economic:true, asnef:false, needRequired:true,
    appointmentTentative:false, minimumIncome:1200,
    criteria: { documents:['DNI','NIE'], incomeByDocument:{ DNI:['Nómina','Autónomo','Jubilación','Pensión contributiva'], NIE:['Nómina','Autónomo'] }, thirdIncomes:['Nómina','Autónomo','Jubilación','Pensión contributiva'], contributiveOnly:true }
  };
  flordent.econQualif = true;
  const step = (title, text, extra = {}) => ({title, text:()=>text, ...extra});
  SCRIPT_TEMPLATES.flordent_estetica = {
    label:'Flordent estética', icon:'⭐', rebates:[],
    steps:[
      step('Saludo, encaje y ubicación', 'Hola, [Nombre]. Te llamo de Flordent estética, en Vilanova i la Geltrú, porque solicitaste información sobre un tratamiento de medicina estética. ¿Es correcto?\n\nEstamos en Calle Pere Jacas, 19, en Vilanova i la Geltrú. ¿Te suena la zona?\n\nSi no conoce la zona: No pasa nada. Cuando terminemos te enviaremos por WhatsApp la ubicación exacta y el enlace de Google Maps para que puedas encontrar la clínica fácilmente.'),
      step('Identificar el tratamiento y la necesidad', 'Perfecto, [Nombre]. Antes de continuar, te informo de que esta llamada puede ser grabada por motivos de calidad.\n\nPerfecto. Para orientarte bien, ¿qué tratamiento es el que te interesa principalmente?\n\nAUMENTO / HIDRATACIÓN DE LABIOS\nPerfecto. ¿Qué te gustaría mejorar principalmente: la hidratación, la definición, el volumen o alguna pequeña asimetría?\nPerfecto. En este tratamiento se busca trabajar los labios de forma personalizada para mejorar su hidratación y definición y, si lo deseas, aportar algo de volumen de una forma equilibrada y natural.\nLa idea es realzar tus labios sin perder la naturalidad ni cambiar tu expresión.\n\nNEUROMODULADORES\nPerfecto. ¿Lo que más te preocupa son las arrugas de la frente, el entrecejo, las patas de gallo o un poco todo?\nEntiendo. En este tratamiento se busca suavizar las líneas de expresión relajando de forma selectiva la musculatura, pero manteniendo una expresión natural.\nLa idea no es dejar el rostro rígido o inexpresivo, sino conseguir una apariencia más descansada y natural.\n\nFULL FACE + RECOLAGENIZACIÓN\nPerfecto. En ese caso, ¿qué es lo que más te gustaría mejorar actualmente de tu rostro?\nEscuchar y resumir.\nEntiendo. En el Full Face se hace una valoración global porque no se trabaja solamente una zona, sino el equilibrio general del rostro.\nSegún cada caso pueden combinarse diferentes técnicas para trabajar proporciones, soporte, definición y también la calidad de la piel.'),
      step('Explicación de cita y cualificación económica obligatoria', 'La primera cita de valoración es totalmente gratuita. Durante esa visita, el especialista revisará tu caso, te explicará el tratamiento más adecuado para ti y te entregará un presupuesto personalizado.\nAdemás, la clínica trabaja con una entidad financiera, por lo que muchos pacientes pueden acceder al tratamiento mediante cuotas y no tienen que asumir el importe completo de una sola vez. En caso de necesitarlo, para comprobar qué opción podemos ofrecerte:\n¿Qué situación laboral o de ingresos tienes tú ahora mismo?\n\nSi menciona solamente «Trabajo»: Genial. Te pregunto porque las financieras diferencian entre nómina, autónomos o pensión. ¿Cómo recibes tú tus ingresos?\n\nPerfecto. Y aproximadamente, ¿tus ingresos mensuales son de al menos 1.200 euros?\n\nSI TIENE 1.200 € O MÁS: pasar al siguiente bloque.\n\nSI TIENE MENOS DE 1.200 €:\nTe cuento, [Nombre]: Para esta campaña específica de salud estética, trabajamos con una entidad financiera externa que es la que gestiona las cuotas. Actualmente, sus condiciones de aprobación son muy estrictas y, por un tema de su propio sistema de riesgos, solo nos permiten tramitar solicitudes con ingresos de al menos 1.200 €.\nMe sabe fatal, porque me encantaría poder darte el hueco ya mismo, pero el sistema no me deja avanzar. ¿Te parece que te avise si cambian estas condiciones?\nFINALIZAR LLAMADA.', {note:'Filtro obligatorio de campaña: mínimo 1.200 €/mes. Financiación entre 12 y 24 meses según la entidad. No equivale a aprobación bancaria.'}),
      step('Documentación para financiación', 'DNI: nómina, pensión contributiva/jubilación, terceros con nómina/pensión/autónomos o autónomos.\nNIE: nómina, terceros con nómina/pensión/autónomos o autónomos.'),
      step('Verificación de datos', 'Antes de reservar la cita, necesito confirmar tus datos para dejar todo correctamente registrado.\n¿Me confirmas tu nombre y apellidos completos, por favor?\n\nSi solo proporciona el nombre: Perfecto, [Nombre]. ¿Me puedes facilitar también tus apellidos? Es simplemente para que la ficha quede registrada correctamente.\nPerfecto, lo actualizo.'),
      step('Agendamiento', '¿Te viene mejor venir por la mañana o por la tarde?\nSegún disponibilidad real, ofrecer un único horario concreto dentro de las próximas 72 horas.\nPerfecto. Tengo disponible el [día] a las [hora]. ¿Te viene bien?\n\nSi acepta: Perfecto, te lo dejo reservado.\nSi no puede: No pasa nada. Tengo otra opción dentro de los próximos días: [día] a las [hora]. ¿Te encaja mejor esa?'),
      step('Cierre final', 'Perfecto, [Nombre]. Entonces tu cita quedó programada para el [día] a las [hora], en Flordent Estètic, Calle Pere Jacas, 19, Vilanova i la Geltrú.\nAhora te envío por WhatsApp la información de la cita y la ubicación para que la tengas a mano.\n¿Tienes alguna duda rápida antes de finalizar?\nSi no tiene dudas: Perfecto, [Nombre]. Muchas gracias y nos vemos el [día] a las [hora]. ¡Que tengas un buen día!')
    ]
  };

  // Resolución de pendientes por el manager. Las reglas sin respuesta no cambian.
  const oneReschedule = new Set(['palomero','ivoria','barrientos','smiledent-gijon','smailo','smailo-coslada','dental-star-as-cancelas']);
  const current = new Date();
  const todayKey = `${current.getFullYear()}-${String(current.getMonth()+1).padStart(2,'0')}-${String(current.getDate()).padStart(2,'0')}`;
  function datedRow(row) {
    const iso = String(row.day).match(/(\d{4})-(\d{2})-(\d{2})/);
    const dates = [...String(row.day).matchAll(/(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?/g)];
    if (iso) return { end:iso[0], label:`${iso[3]}/${iso[2]}/${iso[1]}` };
    if (!dates.length) return null;
    const end = dates.at(-1);
    const year = end[3] || OMNI_MASTER.date.slice(0,4);
    return { end:`${year}-${end[2].padStart(2,'0')}-${end[1].padStart(2,'0')}`, label:row.day + (end[3] ? '' : ` (${year})`) };
  }
  for (const clinic of CLINICS_DATA.filter(c=>!c.inactive)) {
    OMNI_APPOINTMENT_RULES[clinic.id].maxReschedules = oneReschedule.has(clinic.id) ? 1 : 2;
    const schedule = CLINIC_SCHEDULES[clinic.id];
    for (const data of Object.values(schedule.byTreatment)) {
      if (data.scheduleRows?.some(row=>datedRow(row))) {
        data.archivedScheduleRows = data.scheduleRows.filter(row=>datedRow(row)?.end < todayKey);
        data.scheduleRows = data.scheduleRows.filter(row=>!datedRow(row) || datedRow(row).end >= todayKey);
        data.horarios = data.scheduleRows.map(row => {
          const special = datedRow(row);
          return `${row.variant ? row.variant + ' — ' : ''}${special ? 'Fecha especial · ' + special.label : row.day}: ${row.time}`;
        }).join('\n') || 'Sin fechas de atención vigentes publicadas. Consultar disponibilidad con la clínica.';
      }
      if (/^Sin condiciones de financiación especificadas/.test(data.financing || '')) data.financing = 'Información específica de financiación no disponible. Consultar en clínica.';
    }
    if (/^Sin condiciones de financiación especificadas/.test(clinic.financing || '')) clinic.financing = 'Información específica de financiación no disponible. Consultar en clínica.';
    if (clinic.id.startsWith('dental-star-')) {
      for (const treatment of clinic.treatments) {
        Object.assign(schedule.byTreatment[treatment], {duracionCita:'30 min', financing:'Las condiciones de financiación se explican en clínica.', qualifDoc:'No se cualifica.', qualifEcon:'No se cualifica.'});
        schedule.byTreatment[treatment].promo = schedule.byTreatment[treatment].promo.split('\n').filter(line=>!/^financiaci[oó]n:/i.test(line)).join('\n');
        OMNI_APPOINTMENT_RULES[clinic.id].treatments[treatment] = {qualification:'none',document:false,economic:false,asnef:false};
      }
      clinic.qualifDoc = clinic.qualifEcon = 'No se cualifica.';
      clinic.financing = 'Las condiciones de financiación se explican en clínica.';
      clinic.promo = clinic.promo.split('\n').filter(line=>!/^financiaci[oó]n:/i.test(line)).join('\n');
      clinic.econQualif = false;
    }
  }
  const caredent = CLINICS_DATA.find(c=>c.id==='caredentjerez');
  caredent.treatments = caredent.treatments.filter(t=>t!=='ortodoncia');
  for (const [id,treatment] of [['marinabaixa','ortodoncia'],['soniadent','implantes'],['los-molinos','ortodoncia']]) {
    const data = CLINIC_SCHEDULES[id].byTreatment[treatment];
    data.promo = '';
    data.offerDescription = 'Valoración y presupuesto en clínica.';
  }
  const martinez = CLINICS_DATA.find(c=>c.id==='martinez-silva');
  martinez.financing = CLINIC_SCHEDULES['martinez-silva'].byTreatment.implantes.financing = 'Hasta 36 meses sin intereses.';
  const ardenneClinic = CLINICS_DATA.find(c=>c.id==='ardenne');
  ardenneClinic.masterIssues = ardenneClinic.masterIssues.filter(s=>!s.includes('Horario no especificado'));
  Object.assign(CLINIC_SCHEDULES.ardenne.byTreatment.implantes, {horarios:'Recoger disponibilidad libre del paciente. La clínica confirma la cita.',duracionCita:''});
  SCRIPT_TEMPLATES.ardenne_master.steps = SCRIPT_TEMPLATES.ardenne_master.steps.map(step=> /confirmación de datos básicos/i.test(step.title) ? {...step,text:()=> 'Antes de pasar tu solicitud a recepción, necesito confirmar tus datos para dejar bien registrada la información. ¿Me confirmas tu nombre y apellidos, por favor?\n¿Qué días y franjas horarias te vienen bien? Recogeremos tu disponibilidad para que la clínica revise las opciones y confirme la cita.'} : step);

  // Pestaña ADEJE del documento validado, leída el 12/10/2026.
  for (const treatment of ['implantes','ortodoncia']) {
    const key = `adeje_${treatment}`;
    const name = treatment === 'implantes' ? 'implantes dentales' : 'ortodoncia';
    const base = SCRIPT_TEMPLATES[treatment];
    SCRIPT_TEMPLATES[key] = {
      label:`Adeje · ${name}`, icon:base.icon, rebates:[],
      steps:[
        {title:'Saludo + Encaje + Ubicación',text:()=>`Hola, [Nombre]. Te llamo de Clínica Dental Adeje porque nos dejaste una solicitud para el tratamiento de ${name}, ¿correcto?\nEstamos ubicados en la Avenida la Constitución 52, en La Postura, Adeje, justo al lado de la Cerrajería La Llave y cerca de la Farmacia Los Olivos. ¿La zona te suena?`,note:'Si no conoce la zona: No hay problema, le enviaremos la ubicación exacta y el enlace de Google Maps por WhatsApp.'},
        {title:'Autoridad + Oferta + Explicación de cita',text:()=> 'Perfecto. Antes de seguir, te explico muy rápido: esta llamada puede ser grabada por motivos de calidad.\nEn Clínica Dental Adeje contamos con profesionales con más de 30 años de experiencia y tenemos laboratorio propio. La primera cita de valoración es totalmente gratuita y, si el doctor lo ve necesario, incluye radiografía sin ningún coste. Además, por haber contactado ahora, entras en la promoción vigente del 20% de descuento, válida solo durante este mes para las primeras reservas.'},
        {title:'Motivo de la visita',text:()=> treatment==='implantes' ? 'Para ayudarte bien, ¿qué es exactamente lo que necesitas? ¿Una rehabilitación completa o solo una pieza en concreto?' : 'Para ayudarte bien, ¿qué es exactamente lo que necesitas? ¿Es un tratamiento desde cero o una revisión de algo que ya llevas?',note:'Escuchar y resumir en una frase: Perfecto, entonces vienes por ______.'},
        {title:'Verificación de datos básicos',text:()=> 'Antes de agendar, necesito confirmar tus datos para abrir bien tu ficha. ¿Me confirmas tu nombre y apellido?\nPerfecto, lo actualizo aquí.'},
        {title:'Refuerzo de valor y compromiso de asistencia',text:()=> 'Como te comentaba, tienes reservado ese 20% de descuento. Eso sí, para que el sistema te mantenga aplicada la promoción, es requisito indispensable asistir a esta primera cita de valoración. Si no asistes, no podrás aprovechar esta promoción nuevamente. Por eso es súper importante que agendemos un día y una hora en los que sepas con total seguridad que vas a poder venir. ¿Te parece bien?'},
        {title:'Agendamiento',text:()=> 'Sabiendo esto, ¿sueles tener más disponibilidad por las mañanas o por las tardes?',note:'Ofrecer un único horario exacto dentro de las próximas 72 horas, según disponibilidad real.',rebate:()=> 'No pasa nada. Tengo otra opción dentro de los próximos 3 días: [alternativa]. Si prefieres una fecha más adelante, guardo tu número y te llamo dos días antes de la fecha que te interesa para darte un hueco. ¿A qué hora te viene bien que te llame ese día?'},
        {title:'Cierre con resumen final',text:c=>`Perfecto, antes de finalizar te hago un resumen:\nTu cita queda programada para el [día] a las [hora], en ${c.name}, ${c.address}. Ahora te envío por WhatsApp la ubicación e información de la cita para que lo tengas más cómodo.\n¿Tienes alguna duda rápida antes de que te lo mande?`}
      ]
    };
    const clinic = CLINICS_DATA.find(c=>c.id==='adeje');
    clinic.scriptOverrides[treatment] = key;
    OMNI_APPOINTMENT_RULES.adeje.treatments[treatment] = {qualification:'none',document:false,economic:false,asnef:false};
    clinic.econQualif = false;
    clinic.masterIssues = clinic.masterIssues.filter(s=>!s.includes('guion Adeje'));
  }
})();

// Actualización 17/10/2026.
(() => {
  const escape = value => String(value || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const labels = {implantes:'implantes dentales',ortodoncia:'ortodoncia',carillas:'carillas',estetica_medica:'medicina estética'};
  function interpolate(text,c) {
    // Los datos de clínica son texto, nunca HTML del documento externo.
    return escape(text).replace(/\[([^\]]+)\]/g,(whole,key)=> {
      const k=key.toLowerCase();
      if(k==='clínica') return escape(c.name);
      if(k==='ciudad') return escape(c.city);
      if(k==='dirección corta') return escape(c.address);
      if(k==='referencia') return escape(c.ref || 'la dirección indicada');
      if(k==='clínica y dirección') return escape(`${c.name}, ${c.address}`);
      if(k==='tratamiento') return escape(labels[c.treatment] || c.treatment);
      if(k.startsWith('puntos de valor')) return escape(c.valuePoints);
      if(k==='promoción' || k.startsWith('mencionar promoción')) return escape(c.promo || 'valoración y presupuesto en clínica');
      if(k==='documentación admitida') return escape(c.qualifDoc);
      if(k==='situación económica admitida') return escape(c.qualifEcon);
      return whole;
    }).replace(/, cerca de la dirección indicada/g,'');
  }
  const previousCarillas = SCRIPT_TEMPLATES.carillas;
  for(const [name,source] of Object.entries(OMNI_SCRIPT_SOURCES_17)) {
    const steps=source.steps.filter(s=>s.text.trim()).map(s=>({
      title:s.title, text:c=>interpolate(s.text,c),
      ...(s.rebate ? {rebate:c=>interpolate(s.rebate,c)} : {}),
      ...(/cualificación económica/i.test(s.title) ? {condition:'econQualif',note:c=>`Criterios de esta clínica:\n${escape(c.qualifEcon)}`} : {})
    }));
    // Los textos variables de oferta solo se muestran cuando existe una oferta.
    for(const s of steps) if(/mini pitch/i.test(s.title) && !['fonseca','apnea'].includes(name)) {
      s.text=c=>buildAuthorityOfferText(c,'Perfecto. Antes de seguir, te explico muy rápido: esta llamada puede ser grabada por motivos de calidad.')+'\nAdemás, la primera cita es totalmente gratuita.';
    }
    for(const s of steps) if(/refuerzo de valor/i.test(s.title)) s.skipIfEmpty='promo';
    SCRIPT_TEMPLATES[`vigente_${name}`]={label:({A:'Implantes · Selectivo A',B:'Implantes · Selectivo B · ASNEF',C:'Implantes · Selectivo C',massana:'Massana Smile',zen:'Zen Dental',parati:'ParaTi Medicina Estética',fonseca:'Implantes · Fonseca y Obando',apnea:'Apnea del sueño',ortodoncia:'Ortodoncia · Selectivo',carillas:'Carillas · Selectivo'})[name],icon:'📋',steps,rebates:source.rebates};
  }
  // La pestaña de carillas acaba en el bloque económico: conservar el cierre anterior.
  SCRIPT_TEMPLATES.vigente_carillas.steps.push(...previousCarillas.steps.slice(5));
  SCRIPT_TEMPLATES.ortodoncia=SCRIPT_TEMPLATES.vigente_ortodoncia;
  SCRIPT_TEMPLATES.carillas=SCRIPT_TEMPLATES.vigente_carillas;
  const standard=['Nómina','Autónomo','Jubilación','Pensión contributiva'];
  for(const clinic of CLINICS_DATA.filter(c=>!c.inactive)) {
    const rules=OMNI_APPOINTMENT_RULES[clinic.id];
    for(const t of clinic.treatments) {
      const rule=rules.treatments[t];
      const data=CLINIC_SCHEDULES[clinic.id].byTreatment[t];
      if(!rule || !data) continue;
      // Cuenta bancaria adicional no equivale a una fuente de ingresos.
      if(rule.criteria?.incomeByDocument && /DNI:\s*\+ cuenta bancaria/i.test(data.qualifEcon)) {
        rule.criteria.incomeByDocument.DNI=standard;
        (rule.criteria.reviewByDocument ||= {}).DNI=standard;
      }
      if(['ortodoncia','carillas'].includes(t) && !['meta','none'].includes(rule.qualification)) {
        Object.assign(rule,{qualification:'operator',document:true,economic:true,needRequired:true});
        clinic.scriptOverrides[t]=t;
        if(/no cualificamos/i.test(data.qualifEcon)) {
          data.qualifEcon='Ingresos regulares: nómina, autónomo, jubilación o tercero con ingresos regulares. Aplicar el guion selectivo actualizado.';
          Object.assign(rule.criteria,{incomes:standard,incomeByDocument:null,thirdIncomes:standard});
        }
      }
      if(t==='implantes' && rule.qualification==='operator' && !['ardenne','adeje','zendental','massana-valladolid','massana-leon'].includes(clinic.id)) {
        const family=['nuno_perez','saludnavarra'].includes(clinic.id)?'C':clinic.id==='fonseca'?'fonseca':rule.asnef?'B':'A';
        clinic.scriptOverrides[t]=`vigente_${family}`;
        if(family==='C') rule.amountRequired=true;
      }
      if(clinic.id.startsWith('massana-')) clinic.scriptOverrides[t]='vigente_massana';
      if(clinic.id==='soniadent' && t==='ortodoncia') {
        rule.asnef=true;
        SCRIPT_TEMPLATES.ortodoncia_sonia={...SCRIPT_TEMPLATES.ortodoncia,steps:[...SCRIPT_TEMPLATES.ortodoncia.steps.slice(0,5),...SCRIPT_TEMPLATES.vigente_B.steps.filter(s=>/incidencias de pago/i.test(s.title)),...SCRIPT_TEMPLATES.ortodoncia.steps.slice(5)]};
        clinic.scriptOverrides[t]='ortodoncia_sonia';
      }
      if(clinic.id==='odos' && t==='apnea') {
        clinic.scriptOverrides[t]='vigente_apnea';
        Object.assign(rule,{qualification:'document',document:true,economic:false,asnef:false});
      }
      if(clinic.id==='massana-leon') {
        const special=data.scheduleRows?.some(r=>r.day.includes('24/10/2026') || r.day.includes('2026-10-24'));
        if(special) data.duracionCita='Habitual: 45 min. Atención especial del 24/10/2026: 30 min.';
      }
    }
    if(['saludnavarra','massana-valladolid','massana-leon','soniadent','zendental'].includes(clinic.id)) clinic.masterIssues=clinic.masterIssues.filter(s=>!s.includes('falta validar sus diferencias'));
    clinic.econQualif=Object.values(rules.treatments).some(r=>r.economic);
  }
  const para=CLINICS_DATA.find(c=>c.id==='parati');
  para.city='Castelló de la Plana';
  para.scriptOverrides.estetica_medica='vigente_parati';
  para.masterIssues=para.masterIssues.filter(s=>!s.includes('falta integrar'));
  OMNI_APPOINTMENT_RULES.parati.treatments.estetica_medica={qualification:'none',document:false,economic:false,asnef:false,needRequired:true};
  const zen=CLINICS_DATA.find(c=>c.id==='zendental');
  zen.scriptOverrides.implantes='vigente_zen';
  Object.assign(OMNI_APPOINTMENT_RULES.zendental.treatments.implantes,{zenRoutes:true,needRequired:true});
  CLINIC_SCHEDULES.fonseca.operationalNotes.push('Priorizar lunes, martes y jueves con la implantóloga. Miércoles y viernes siguen disponibles para valoración general, según la agenda. Confirmado por el manager el 17/10/2026.');
})();

// Presentación de direcciones, confirmada por el manager el 19/10/2026.
(() => {
  function splitAddress(value) {
    let address='', reference='', depth=0;
    const references=[];
    for(const char of String(value || '')) {
      if(char==='(') { if(depth++) reference+=char; }
      else if(char===')' && depth) { if(--depth) reference+=char; else {references.push(reference.trim());reference='';} }
      else if(depth) reference+=char;
      else address+=char;
    }
    // Si falta un cierre, conservar ese fragmento en la dirección.
    if(depth) address+='('+reference;
    return {address:address.replace(/\s+/g,' ').replace(/\s+([.,;])/g,'$1').replace(/[,;.]\s*$/,'').trim(),references};
  }
  for(const clinic of CLINICS_DATA) {
    const parsed=splitAddress(clinic.address);
    if(parsed.references.length) {
      clinic.sourceAddress=clinic.address;
      clinic.address=parsed.address;
      clinic.ref=[...new Set([clinic.ref,...parsed.references].filter(Boolean))].join('; ');
    }
    for(const site of CLINIC_SCHEDULES[clinic.id]?.sedes || []) {
      const parsed=splitAddress(site.direccion);
      if(parsed.references.length) {
        site.sourceAddress=site.direccion; site.direccion=parsed.address;
        site.referencia=[site.referencia,...parsed.references].filter(Boolean).join('; ');
      }
    }
  }
})();
